    { id=239, name="Uldaman", isRaid=false, minLevel=35,
      mapID=70, loreFDID=608264, bgFDID=608186, buttonFDID=608225,
      desc="Uldaman is an ancient titan vault buried deep within the earth. It is said the titans sealed away a failed experiment there and then moved on to a new project, related to the genesis of the dwarves. Tales of a fabled treasure containing great knowledge have enticed would-be treasure hunters to dig deeper into the secrets of Uldaman, a task made perilous by the presence of stone defenders, savage troggs, Dark Iron invaders, and other dangers lurking in the lost city.",
      encounters = {
        { id=6910, name="Revelosh", order=1,
          uiMapID=230, x=0.53415298462, y=0.72540998459, rootSection=4820,
          desc="Some luminaries in Ironforge's prestigious Explorers' League have theorized an ancestral link between their people and the troggs, and pointed towards the troggs' hoarding of titan artifacts as a reflection of the dwarves' own reverence for such wondrous devices. If that is true, the trogg known as Revelosh can be considered the trogg equivalent of an archaeologist, although any historically minded adventurers who encounter him would be more inclined to call him a thief.",
          creatures = { {display=5945, file=607757, name="Revelosh"} },
          loot = { {id=7741,pct=40.2}, {id=9389,pct=23.3}, {id=9387,pct=22.7}, {id=9390,pct=21.1}, {id=9388,pct=21.0} },
          sections = {
            { id=4820, title="Chain Lightning", parent=0, child=0, sib=4821, order=1, spell=0, icon=136015, flags=64, cdisp=0,
              body="Revelosh strikes his target with a lightning bolt that arcs to nearby players, inflicting Nature damage to $16006x1 targets." },
            { id=4821, title="Lightning Bolt", parent=0, child=0, sib=0, order=2, spell=0, icon=136048, flags=64, cdisp=0,
              body="Revelosh blasts his current target with lightning, inflicting Nature damage." },
          },
        },
        { id=6906, name="The Lost Dwarves", order=2,
          uiMapID=230, x=0.58469897509, y=0.92008197308, rootSection=4869,
          desc="Seeking fame and, more importantly, fortune, the three brothers Eric, Olaf, and Baelog took on a contract from the Explorers' League to delve deep into the halls of Uldaman and clear a path for a group of researchers. For these three dwarves, however, \"clearing a path\" unfortunately entailed \"getting hopelessly lost in an ancient labyrinth.\" Proud dwarves to the end, they fight to prevent the secrets of Uldaman and the Explorers' League from falling into the hands of the Horde.",
          creatures = { {display=5710, file=607550, name="The Lost Dwarves"} },
          loot = { {id=9399,pct=87.6}, {id=9400,pct=39.6}, {id=9401,pct=9.3} },
          sections = {
            { id=4869, title="Baelog", parent=0, child=4870, sib=4874, order=1, spell=0, icon=0, flags=0, cdisp=0,
              body="Baelog favors combat, attacking with his sword and bow." },
            { id=4870, title="Strike", parent=4869, child=0, sib=4871, order=2, spell=0, icon=132282, flags=0, cdisp=0,
              body="Baelog strikes his current target, inflicting Physical damage." },
            { id=4871, title="Shoot", parent=4869, child=0, sib=0, order=3, spell=0, icon=132222, flags=0, cdisp=0,
              body="Baelog shoots a player, inflicting Physical damage." },
            { id=4874, title="Eric \"The Swift\"", parent=0, child=4875, sib=4872, order=4, spell=0, icon=0, flags=0, cdisp=0,
              body="Eric favors speed, charging head-first into battle." },
            { id=4875, title="Rushing Charge", parent=4874, child=0, sib=0, order=5, spell=0, icon=132368, flags=0, cdisp=0,
              body="Eric \"The Swift\" charges towards a player, increasing the damage of his next attack." },
            { id=4872, title="Olaf", parent=0, child=4873, sib=0, order=6, spell=0, icon=0, flags=0, cdisp=0,
              body="Olaf favors defense, blocking with his shield." },
            { id=4873, title="Shield Slam", parent=4872, child=0, sib=0, order=7, spell=0, icon=132357, flags=0, cdisp=0,
              body="Olaf slams his target, inflicting Physical damage and stunning them for $8242d." },
          },
        },
        { id=7228, name="Ironaya", order=3,
          uiMapID=230, x=0.37295100093, y=0.73975402117, rootSection=4876,
          desc="The titans did not construct the Uldaman complex directly, but utilized various servants to create its megalithic halls. The Pantheon entrusted the watcher Ironaya with overseeing the construction and maintenance of Uldaman, but as time passed, the once awe-inspiring vault fell to ruin. Within the map chamber, Ironaya has spent millennia in a form of stasis, analyzing the original master plan drawn up by Khaz'goroth and attempting to find a way to restore the complex to its original functionality.",
          creatures = { {display=6089, file=607664, name="Ironaya"} },
          loot = { {id=9407,pct=37.7}, {id=9409,pct=37.7}, {id=9408,pct=20.5} },
          sections = {
            { id=4876, title="Arcing Smash", parent=0, child=0, sib=4877, order=1, spell=0, icon=132338, flags=0, cdisp=0,
              body="Ironaya lashes out in a vicious arc, inflicting Physical damage to all enemies in front of her." },
            { id=4877, title="Knock Away", parent=0, child=0, sib=4878, order=2, spell=0, icon=132939, flags=0, cdisp=0,
              body="Ironaya inflicts Physical damage to her current target, knocking them away." },
            { id=4878, title="War Stomp", parent=0, child=0, sib=0, order=3, spell=0, icon=132091, flags=0, cdisp=0,
              body="Ironaya stomps, inflicting Physical damage to all enemies within $11876A1 yards and stunning them for $11876d." },
          },
        },
        { id=7206, name="Ancient Stone Keeper", order=5,
          uiMapID=230, x=0.47541001439, y=0.44057399035, rootSection=4879,
          desc="One of many golems that staffed and operated the great titan vault, the Ancient Stone Keeper was part of a small group that served as an intermediary between the watchers left in control of the facility and their many servants. With the corruption of the Obsidian Sentinel, the Ancient Stone Keeper is the last of its kind, performing its duty by protecting the secrets of the titans as best it can until its inevitable shutdown.",
          creatures = { {display=10798, file=607538, name="Ancient Stone Keeper"} },
          loot = { {id=9410,pct=47.7}, {id=9411,pct=47.0} },
          sections = {
            { id=4879, title="Sand Storms", parent=0, child=0, sib=0, order=1, spell=0, icon=136022, flags=0, cdisp=0,
              body="Ancient Stone Keeper summons a sand storm that moves towards a player, inflicting physical damage and reducing movement speed of all players within $10093A1 yards." },
          },
        },
        { id=7291, name="Galgann Firehammer", order=6,
          uiMapID=230, x=0.26776000857, y=0.32786899805, rootSection=4880,
          desc="Reacting to the discovery of Uldaman by Bronzebeard dwarves, the Dark Iron clan mounted an invasion of the vault to stop their ancestral foes from accessing the powerful artifacts within. Galgann Firehammer, a senator from Shadowforge City, was sent to oversee the continued excavation of Uldaman so that the emperor may harness the artifacts' destructive potential against the Dark Irons' enemies.",
          creatures = { {display=6059, file=607606, name="Galgann Firehammer"} },
          loot = { {id=11311,pct=38.1}, {id=9419,pct=19.9}, {id=11310,pct=19.5}, {id=9412,pct=17.7} },
          sections = {
