    { id=241, name="Zul'Farrak", isRaid=false, minLevel=43,
      mapID=209, loreFDID=608267, bgFDID=608191, buttonFDID=608230,
      desc="Zul'Farrak was once the shining jewel of Tanaris, ferociously protected by the cunning Sandfury tribe. Despite the trolls' tenacity, this isolated group was forced to surrender much of its territory throughout history. Now, it appears that Zul'Farrak's inhabitants are creating a horrific army of undead trolls to conquer the surrounding region. Other disturbing rumors tell of an ancient creature sleeping within the city--one that, if awakened, will rain death and destruction across Tanaris.",
      encounters = {
        { id=7272, name="Theka the Martyr", order=0,
          uiMapID=219, x=0.53142100573, y=0.26229500771, rootSection=5005,
          desc="Long ago, the martyr Theka was slain in the brutal war between the qiraji and the trolls. Zul'Farrak still stands because of his brave sacrifice. Even in death he maintains a vigil over his beloved city, and it is said that the dozens of insectoid warriors who killed him were cursed to live as mindless scarabs, scuttling at the martyr's side.",
          creatures = { {display=6696, file=607793, name="Theka the Martyr"} },
          loot = { {id=10660,pct=43.7} },
          sections = {
            { id=5005, title="Fevered Plague", parent=0, child=0, sib=5006, order=1, spell=0, icon=136066, flags=1088, cdisp=0,
              body="Theka the Martyr plagues a player, inflicting $8600s1 Nature damage and an additional $8600s2 Nature damage every $8600t2 sec for $8600d." },
            { id=5006, title="Shadow Transformation", parent=0, child=0, sib=29862, order=2, spell=0, icon=136121, flags=0, cdisp=0,
              body="At 30% remaining health Theka the Martyr transforms, increasing his resistance to Physical and Shadow damage by $11089s2% for $11089d." },
            { id=29862, title="Shadow Bolt Volley", parent=0, child=0, sib=29863, order=3, spell=0, icon=136197, flags=64, cdisp=0,
              body="Theka hurls missiles of dark magic, inflicting $17228s1 Shadow damage to nearby enemies." },
            { id=29863, title="Shadow Word: Pain", parent=0, child=0, sib=29864, order=4, spell=0, icon=136207, flags=128, cdisp=0,
              body="Theka utters a word of darkness, inflicting $15654s1 Shadow damage to an enemy every $15654t1 sec for $15654d." },
            { id=29864, title="Curse of the Martyr", parent=0, child=0, sib=0, order=5, spell=0, icon=134933, flags=35, cdisp=0,
              body="Theka curses a random target, transforming them into a scarab for $450933d and sounding the toll of persecution which draws the attention of nearby scarabs." },
          },
        },
        { id=7795, name="Hydromancer Velratha", order=1,
          uiMapID=219, x=0.32869398594, y=0.38115599751, rootSection=4978,
          desc="Unlike most of the Sandfury trolls, Hydromancer Velratha has traveled the world, collecting knowledge and artifacts to help her command Zul'Farrak's sacred waters. Although the hydromancer's actions have earned her many enemies abroad, she sees the incredible power at her command as justification for her past misdeeds.",
          creatures = { {display=6685, file=607652, name="Hydromancer Velratha"} },
          loot = { {id=9234,pct=61.5}, {id=10661,pct=49.4} },
