        { id=8127, name="Antu'sul", order=1,
          uiMapID=219, x=0.64617502689, y=0.27663901448, rootSection=4986,
          desc="Antu'sul prefers his sul'lithuz basilisks strong and ruthless. He treats these scaled beasts like family, and he is known to strike down anyone--even fellow trolls--who harm his precious children. Rather than give his opponents a proper burial, Antu'sul allows the basilisks to feast on whoever dares cross him.",
          creatures = { {display=7353, file=607541, name="Antu'sul"} },
          loot = { {id=9641,pct=35.0}, {id=9640,pct=32.0}, {id=9639,pct=17.8}, {id=9379,pct=1.0} },
