        { id=7273, name="Gahz'rilla", order=4,
          uiMapID=219, x=0.280941993, y=0.3827829957, rootSection=4981,
          desc="Legend has it that Gahz'rilla was an adored pet of the Old Gods, or even a demigod in her own right. Whatever the truth is, the Sandfury trolls have worshiped this monstrous hydra for thousands of years. Ever wary of the beast's icy wrath, the trolls will only rouse Gahz'rilla when they have plentiful sacrifices to sate the ravenous creature's appetite.",
          creatures = { {display=7271, file=607614, name="Gahz'rilla"} },
          loot = { {id=9467,pct=45.5}, {id=9469,pct=45.2} },
