        { id=7796, name="Nekrum & Sezz'ziz", order=5,
          uiMapID=219, x=0.29644799232, y=0.17418000102, rootSection=5019,
          desc="Nekrum Gutchewer has mysteriously lived well past his natural life, but his decaying body remains strong enough to aid Sezz'ziz. Together, these two trolls have gathered sacrifices to the mythic beast Gahz'rilla, who slumbers at the city's heart. Many troll followers eagerly await the terrifying creature's awakening, and they will do anything to see the ritual through.",
          creatures = { {display=6690, file=607723, name="Nekrum & Sezz'ziz"} },
