    { id=228, name="Blackrock Depths", isRaid=false, minLevel=48,
      mapID=230, loreFDID=608235, bgFDID=608157, buttonFDID=608196,
      desc="The smoldering Blackrock Depths are home to the Dark Iron dwarves and their emperor, Dagran Thaurissan. Like his predecessors, he serves under the iron rule of Ragnaros the Firelord, a merciless being summoned into the world centuries ago. The presence of chaotic elementals has attracted Twilight's Hammer cultists to the mountain domain. Along with Ragnaros' servants, they have pushed the dwarves toward increasingly destructive ends that could soon spell doom for all of Azeroth.",
      encounters = {
        { id=9018, name="High Interrogator Gerstahn", order=1,
          uiMapID=242, x=0.47404399514, y=0.92213100195, rootSection=4630,
          desc="The Twilight's Hammer cultist Gerstahn has always indulged in life's finer things: exotic foods, fine clothes, and gem-encrusted torture tools. Day and night, her prisoners' bloodcurdling cries echo throughout the Dark Iron clan's infamous Detention Block. Gerstahn proudly calls this horrific noise her symphony of screams, and she is always eager to add another voice to the chorus.",
          creatures = { {display=8761, file=607644, name="High Interrogator Gerstahn"} },
          loot = { {id=11140,pct=53.0}, {id=11624,pct=28.4}, {id=11625,pct=13.6}, {id=22240,pct=11.9}, {id=11626,pct=9.2} },
          sections = {
            { id=4630, title="Mana Burn", parent=0, child=0, sib=4631, order=1, spell=0, icon=136170, flags=64, cdisp=0,
              body="High Interrogator Gerstahn inflicts Shadow damage to a player and drains a portion of their mana." },
            { id=4631, title="Psychic Scream", parent=0, child=0, sib=4632, order=2, spell=0, icon=136184, flags=128, cdisp=0,
              body="High Interrogator Gerstahn causes all players within $13704a1 yards to run in fear for $13704d." },
            { id=4632, title="Shadow Word: Pain", parent=0, child=0, sib=4633, order=3, spell=0, icon=136207, flags=128, cdisp=0,
              body="High Interrogator Gerstahn inflicts a player with Shadow Word: Pain.  Shadow Word: Pain inflicts Shadow damage every $14032t1 seconds for $14032d." },
            { id=4633, title="Shadow Shield", parent=0, child=0, sib=0, order=4, spell=0, icon=136121, flags=128, cdisp=0,
              body="High Interrogator Gerstahn surrounds herself in a dark shield, absorbing up to $12040s1 damage for $12040d." },
          },
        },
        { id=9025, name="Lord Roccor", order=2,
          uiMapID=242, x=0.55601102114, y=0.67008197308, rootSection=4472,
          desc="Lord Roccor loathes the scheming and backstabbing of his fellow fire elementals. To avoid serving alongside his kind in the Molten Core, the mighty being purposefully angered the Firelord. Roccor's risky gambit paid off: he was expelled from the core and forced to guard Blackrock Depths in isolation.",
          creatures = { {display=5781, file=607697, name="Lord Roccor"} },
          loot = { {id=11632,pct=24.4}, {id=11631,pct=24.1}, {id=22234,pct=23.4}, {id=22397,pct=19.9}, {id=11630,pct=18.4}, {id=11813,pct=18.3} },
          sections = {
            { id=4472, title="Ground Tremor", parent=0, child=0, sib=4473, order=1, spell=0, icon=136025, flags=0, cdisp=0,
              body="Lord Roccor stuns all players within $6524a1 yards for $6524d." },
            { id=4473, title="Earth Shock", parent=0, child=0, sib=4474, order=2, spell=0, icon=136026, flags=0, cdisp=0,
              body="Lord Roccor inflicts Nature damage to a player and interrupts any spell they are casting." },
            { id=4474, title="Flame Shock", parent=0, child=0, sib=0, order=3, spell=0, icon=135813, flags=128, cdisp=0,
              body="Lord Roccor inflicts Fire damage to a player.  Flame Shock continues to burn that player for Fire damage every $13729t2 seconds for $13729d." },
          },
        },
        { id=9319, name="Houndmaster Grebmar", order=3,
          uiMapID=242, x=0.53500199318, y=0.57346600294, rootSection=4626,
          desc="Grebmar Fleabeard's hounds are the only family he's ever known. Long ago, the orphaned dwarf began breeding canines to serve as companions and guard dogs. When the houndmaster isn't patrolling Blackrock Depths with his loyal beasts, he often treats them to the Grim Guzzler's finest Dark Iron ale.",
          creatures = { {display=9212, file=607647, name="Houndmaster Grebmar"} },
          loot = { {id=11627,pct=42.9}, {id=11623,pct=19.1}, {id=11628,pct=9.5}, {id=11629,pct=9.1} },
          sections = {
            { id=4626, title="Dual Wield", parent=0, child=0, sib=4627, order=1, spell=0, icon=132147, flags=0, cdisp=0,
              body="Houndmaster Gremar wields a weapon in each hand." },
            { id=4627, title="Demoralizing Shout", parent=0, child=0, sib=4628, order=2, spell=0, icon=132366, flags=0, cdisp=0,
              body="Houndmaster Grebmar reduces the attack power of all players within $13730a1 yards for $13730d." },
            { id=4628, title="Pummel", parent=0, child=0, sib=6439, order=3, spell=0, icon=132938, flags=0, cdisp=0,
              body="Houndmaster Grembar inflicts Physical damage to a player and interrupts any spell casting for $15615d." },
            { id=6439, title="Bloodlust", parent=0, child=0, sib=4629, order=4, spell=0, icon=136012, flags=128, cdisp=0,
              body="Houndmaster Grebmar sends an ally into a frenzy, increasing their attack speed by $21049s1% for $21049d." },
            { id=4629, title="Run Away! Run Away!", parent=0, child=0, sib=0, order=5, spell=0, icon=0, flags=0, cdisp=0,
              body="Houndmaster Grebmar will flee at 15% health remaining." },
          },
        },
        { id=10096, name="Ring of Law", order=4,
          uiMapID=242, x=0.49778500199, y=0.64579600096, rootSection=4547,
          desc="There is only one punishment for crimes committed against the Dark Iron dwarves: death. Ancient tradition calls for the guilty to pay the blood price in the Ring of the Law by battling savage creatures gathered from across Azeroth. To date, it is unknown if anyone has ever survived this brutal crucible.",
          creatures = { {display=9329, file=608314, name="Ring of Law"} },
          sections = {
            { id=4547, title="You Shall be Judged!", parent=0, child=4566, sib=0, order=1, spell=0, icon=0, flags=0, cdisp=0,
              body="High Justice Grimstone sentences players to death in the Ring of Law.  Players must face randomly selected monsters and defeat them to proceed." },
            { id=4566, title="Opening Statements", parent=4547, child=4548, sib=4567, order=2, spell=0, icon=0, flags=0, cdisp=0,
              body="High Justice Grimstone first selects a random monster for players to fight in the Ring of Law.  Two waves of the same monster type will attack players.  Possible monsters appear in the sections that follow." },
            { id=4548, title="Burrowing Thundersnout", parent=4566, child=4549, sib=4555, order=3, spell=0, icon=0, flags=0, cdisp=8184,
              body="" },
            { id=4549, title="Lizard Bolt", parent=4548, child=0, sib=4550, order=4, spell=0, icon=136048, flags=64, cdisp=0,
              body="The Burrowing Thundersnout inflicts Nature damage to a player." },
            { id=4550, title="Thunderclap", parent=4548, child=0, sib=4551, order=5, spell=0, icon=136105, flags=0, cdisp=0,
              body="The Burrowing Thundersnout inflicts Nature damage to all players within $15548a1 yards.  Thunderclap reduces the melee attack speed of players by $15548s3% and their movement speed by 55% for $15548d." },
            { id=4551, title="Disjunction", parent=4548, child=0, sib=0, order=6, spell=0, icon=135990, flags=128, cdisp=0,
              body="The Burrowing Thundersnout affects players within $14533a1 yards with Disjunction. Disjunction increases the Fire, Frost, and Arcane damage taken by the player by $14533s1% for $14533d." },
            { id=4555, title="Borer Beetle", parent=4566, child=4574, sib=4556, order=7, spell=0, icon=0, flags=0, cdisp=7470,
