              body="Warder Stilgiss shields himself against Frost damage for $15044d or until Frost Ward absorbs too much Frost damage." },
            { id=6455, title="Verek", parent=0, child=6456, sib=0, order=6, spell=0, icon=0, flags=0, cdisp=9019,
              body="" },
