        { id=8983, name="Golem Lord Argelmach", order=11,
          uiMapID=243, x=0.36475399137, y=0.65163898468, rootSection=4501,
          desc="Argelmach's lifelong obsession with immortality drove him to forge enchanted constructs in his own image. Rumor has it that he has also dabbled in some form of black magic that would allow the golem lord's new creations to act as vessels for his spirit should his flesh-and-blood body be destroyed.",
          creatures = { {display=8759, file=607618, name="Golem Lord Argelmach"} },
          loot = { {id=11823,pct=37.2}, {id=11822,pct=36.8}, {id=11669,pct=9.5}, {id=11819,pct=8.9} },
          sections = {
            { id=4501, title="Chain Lightning", parent=0, child=0, sib=4502, order=1, spell=0, icon=136015, flags=0, cdisp=0,
              body="Golem Lord Argelmach inflicts Nature damage to a player.  Chain Lightning jumps to a nearby player within 15 yards and inflicts Nature damage again.  Chain Lightning will hit up to $15305x targets." },
            { id=4502, title="Shock", parent=0, child=0, sib=4503, order=2, spell=0, icon=136115, flags=0, cdisp=0,
              body="Golem Lord Argelmach inflicts Nature damage to a player." },
            { id=4503, title="Lightning Shield", parent=0, child=0, sib=0, order=3, spell=0, icon=136051, flags=128, cdisp=0,
              body="Golem Lord Argelmach surrounds himself with $15507n balls of lightning.  There is a $15507h% chance that the Lightning Shield will retaliate against any attack players make. When retaliating, the Lightning Shield inflicts Nature damage and consumes one ball of lightning.  The Lightning Shield persists until all the balls of lightning are consumed." },
          },
        },
        { id=9537, name="Hurley Blackbreath", order=12,
          uiMapID=243, x=0.50566798449, y=0.70477801561, rootSection=4494,
          desc="To say Blackbreath is a regular at the Grim Guzzler would be something of an understatement. In over a decade, the mischievous drunkard has left the tavern only once to steal a top-secret recipe for Thunderbrew Lager. Blackbreath has occasionally sobered up enough to make the concoction himself, and he claims it grants unimaginable strength and courage.",
          creatures = { {display=8658, file=607650, name="Hurley Blackbreath"} },
          loot = { {id=12793,pct=29.5}, {id=18044,pct=23.9}, {id=22275,pct=23.0}, {id=18043,pct=20.4}, {id=18653,pct=16.9}, {id=11742,pct=13.8}, {id=11612,pct=12.4}, {id=12791,pct=10.2}, {id=2663,pct=9.0}, {id=2662,pct=8.5}, {id=11735,pct=7.6}, {id=11325,pct=1.6}, {id=11602,pct=0.2}, {id=18592,pct=0}, {id=13483,pct=0}, {id=15759,pct=0} },
          sections = {
            { id=4494, title="Flame Breath", parent=0, child=0, sib=4495, order=1, spell=0, icon=135805, flags=0, cdisp=0,
              body="Hurley Blackbreath inflicts Fire damage to all players in a cone in front of him." },
            { id=4495, title="Drunken Rage", parent=0, child=0, sib=0, order=2, spell=0, icon=136224, flags=0, cdisp=0,
              body="Hurley Blackbreath increases his attack speed by $14872s1% and his Physical damage is increased by $14872s2%.  This effect lasts for $14872d." },
          },
        },
        { id=9502, name="Phalanx", order=13,
          uiMapID=243, x=0.45820599794, y=0.56474500895, rootSection=4504,
          desc="Until recently, drunken brawls raged within the Grim Guzzler on an almost daily basis. Barkeep Plugger Spazzring has reduced the frequency of these scuffles with Phalanx, a mighty golem bouncer programmed to maintain order in the tavern and eliminate raucous patrons with extreme force.",
          creatures = { {display=8177, file=607740, name="Phalanx"} },
          loot = { {id=11745,pct=30.7}, {id=22212,pct=25.1}, {id=11744,pct=24.9}, {id=11743,pct=8.4} },
          sections = {
            { id=4504, title="Mighty Blow", parent=0, child=0, sib=4505, order=1, spell=0, icon=132939, flags=0, cdisp=0,
              body="Phalanx inflicts Physical damage to a player and knocks them back." },
            { id=4505, title="Thunderclap", parent=0, child=0, sib=4506, order=2, spell=0, icon=136105, flags=0, cdisp=0,
              body="Phalanx inflicts Nature damage to all players within $15588a1 yards.  Thunderclap slows the melee attack speed of all players it hits by $15588s3% and reduces their movement speed by 57% for $15588d." },
            { id=4506, title="Fireball Volley", parent=0, child=0, sib=0, order=3, spell=0, icon=135812, flags=0, cdisp=0,
              body="Phalanx inflicts Fire damage to all players within $15285A1 yards." },
          },
        },
        { id=9499, name="Plugger Spazzring", order=15,
          uiMapID=243, x=0.47721999884, y=0.65712201595, rootSection=4485,
          desc="They say that at the Grim Guzzler everyone knows your name. This sense of camaraderie is due to the hard work of Spazzring, a leper gnome who sought a new life in Blackrock Depths after the fall of Gnomeregan. Despite his history of dabbling with evil as a warlock, he takes pride in his job as the tavern's barkeep, making sure that his patrons' mugs never run dry.",
          creatures = { {display=8652, file=607741, name="Plugger Spazzring"} },
          loot = { {id=11735,pct=0}, {id=18043,pct=0}, {id=22275,pct=0}, {id=18044,pct=0}, {id=18592,pct=0}, {id=11612,pct=0}, {id=2662,pct=0}, {id=2663,pct=0}, {id=11742,pct=0}, {id=12793,pct=0}, {id=12791,pct=0}, {id=18653,pct=0}, {id=13483,pct=0}, {id=15759,pct=0}, {id=11325,pct=0}, {id=11602,pct=0} },
          sections = {
            { id=4485, title="Owner of the Grim Guzzler", parent=0, child=0, sib=4486, order=1, spell=0, icon=0, flags=32, cdisp=0,
              body="Plugger Spazzring carries the Key to the Grim Guzzler.  If players pick Plugger Spazzring's pockets he will alert all of his patrons to attack players.  This changes all of the Grim Guzzler's patrons from neutral to aggressive." },
            { id=4486, title="Shadowbolt", parent=0, child=0, sib=4487, order=2, spell=0, icon=136197, flags=0, cdisp=0,
              body="Plugger Spazzring inflicts Shadow damage to a player." },
            { id=4487, title="Immolate", parent=0, child=0, sib=4488, order=3, spell=0, icon=135817, flags=128, cdisp=0,
              body="Plugger Spazzring inflicts Fire damage to a player.  Immolate continues burning that player for Fire damage every $12742t1 seconds for $12742d." },
            { id=4488, title="Demon Armor", parent=0, child=0, sib=4489, order=4, spell=0, icon=136185, flags=128, cdisp=0,
              body="Plugger Spazzring is protected by demonic energies.  Demon Armor increases Plugger Spazzring's armor, Shadow resistance, and health regeneration." },
            { id=4489, title="Curse of Tongues", parent=0, child=0, sib=4490, order=5, spell=0, icon=136140, flags=260, cdisp=0,
              body="Plugger Spazzring curses a player to speak in Demonic.  Players under the Curse of Tongues have their casting speed reduced by $13338s1% for $13338d." },
            { id=4490, title="Banish", parent=0, child=0, sib=0, order=6, spell=0, icon=136135, flags=128, cdisp=0,
              body="Plugger Spazzring banishes a player to the void.  Banished players are unable to take any actions and are immune to all attacks and spells." },
          },
        },
        { id=9156, name="Ambassador Flamelash", order=16,
          uiMapID=243, x=0.53825098276, y=0.48565599322, rootSection=4482,
          desc="For his unwavering service to Ragnaros, Flamelash ascended to the rank of ambassador to the Dark Iron clan. This depraved being initially despised his dwarven allies, but he has come to respect their penchant for destruction. As a show of solidarity, Flamelash guards the Chamber of Enchantment, a sacred location used by the dwarves to empower their weaponry.",
          creatures = { {display=8329, file=607535, name="Ambassador Flamelash"} },
          loot = { {id=11812,pct=39.6}, {id=11814,pct=38.4}, {id=11809,pct=9.6}, {id=11832,pct=8.7}, {id=11808,pct=0.3}, {id=23320,pct=0} },
          sections = {
            { id=4482, title="Burning Spirit", parent=0, child=4483, sib=4484, order=1, spell=0, icon=0, flags=32, cdisp=4607,
              body="Burning Spirits spawn at the 7 Flame Runes located around the edge of Ambassador Flamelash's room.  Burning Spirits will move toward Ambassador Flamelash and cast Burning Spirit." },
            { id=4483, title="Burning Spirit", parent=4482, child=0, sib=0, order=2, spell=0, icon=135805, flags=0, cdisp=0,
              body="Burning Spirits will sacrifice themselves to give Burning Spirit to Ambassador Flamelash when they get within 1 yard of him.\nBurning Spirit increases the damage of Ambassador Flamelash by $14744s1% and increases his size by $14744s2%.  Burning Spirit stacks up to $14744u charges." },
            { id=4484, title="Fire Blast", parent=0, child=0, sib=0, order=3, spell=0, icon=135817, flags=0, cdisp=0,
              body="Ambassador Flamelash inflicts $15574s1 Fire damage to players he hits in melee." },
          },
        },
        { id=9039, name="The Seven", order=17,
          uiMapID=243, x=0.53825098276, y=0.24795100093, rootSection=4471,
          desc="Centuries ago, sorcerer-thane Thaurissan and seven of his most powerful Dark Iron allies accidentally summoned Ragnaros into Azeroth and damned their entire clan to enslavement. Although the Seven perished during the ritual, their restless spirits still linger in Blackrock Depths, cursed to serve their elemental master and the current Dark Iron ruler.",
          creatures = { {display=8687, file=607587, name="The Seven"} },
          loot = { {id=11925,pct=0}, {id=11926,pct=0}, {id=11929,pct=0}, {id=11927,pct=0}, {id=11920,pct=0}, {id=11923,pct=0}, {id=11922,pct=0}, {id=11921,pct=0} },
