        { id=5312, name="Wardens of the Dream", order=3,
          uiMapID=220, x=0.49915099144, y=0.87030899525, rootSection=6114,
          desc="Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.",
          creatures = { {display=7553, file=608311, name="Wardens of the Dream"} },
          sections = {
            { id=6114, title="The Wardens of the Dream", parent=0, child=4942, sib=0, order=1, spell=0, icon=0, flags=0, cdisp=0,
              body="Dreamscythe, Weaver, Morphaz and Hazzas defend the Shade of Eranikus with their lives." },
            { id=4942, title="Acid Breath", parent=6114, child=0, sib=4943, order=2, spell=0, icon=136007, flags=0, cdisp=0,
              body="The Wardens of the Dream breath acid, inflicting Nature damage instantly and additional Nature damage every $12884t1 seconds for $12884d to all players in front of them." },
            { id=4943, title="Wing Flap", parent=6114, child=0, sib=0, order=3, spell=0, icon=136022, flags=0, cdisp=0,
              body="The Wardens of the Dream thrash their wings, knocking all players in front of them backwards." },
          },
        },
        { id=5709, name="Shade of Eranikus", order=7,
          uiMapID=220, x=0.6707649827, y=0.87704902887, rootSection=4950,
          desc="Eranikus, former consort to Ysera the Dreamer, was sent to guard the ruins of Atal'Hakkar and prevent Hakkar's emergence. Once within the temple, he and his retinue were corrupted by its dark forces, and he became a shade, pulled between the realms of the Emerald Dream and the physical plane. Despite his corruption, Eranikus may still call upon his powers as a green dragon to spew corrosive acid at his enemies or trap them in a deep slumber.",
          creatures = { {display=7806, file=607768, name="Shade of Eranikus"} },
          loot = { {id=10454,pct=63.7}, {id=10829,pct=31.8}, {id=10833,pct=30.9}, {id=10835,pct=28.9}, {id=10836,pct=26.3}, {id=10828,pct=16.4}, {id=10837,pct=14.2}, {id=10847,pct=0.2} },
