    { id=229, name="Lower Blackrock Spire", isRaid=false, minLevel=55,
      mapID=229, loreFDID=608236, bgFDID=608158, buttonFDID=608197,
      desc="This imposing fortress, carved into the fiery core of Blackrock Mountain, represented the might of the Dark Iron clan for centuries. More recently, the black dragon Nefarian and his spawn seized the keep's upper spire and ignited a brutal war against the dwarves. The draconic armies have since allied with Warchief Rend Blackhand and his false Horde. This combined force lords over the spire, conducting horrific experiments to bolster its ranks while plotting the meddlesome Dark Irons' downfall.",
      encounters = {
        { id=9196, name="Highlord Omokk", order=1,
          uiMapID=252, x=0.38661199808, y=0.59016400576, rootSection=4523,
          desc="Omokk rules over the spire's ogres with an iron fist. Many underlings have challenged him to single combat in the hopes of seizing the highlord's title, but all have fallen without landing a solitary blow. This mysterious phenomenon has led to rumors that dark magic is protecting Omokk.",
          creatures = { {display=11565, file=607645, name="Highlord Omokk"} },
          loot = { {id=12534,pct=89.8}, {id=12336,pct=27.5}, {id=13167,pct=14.6}, {id=13166,pct=14.0}, {id=13169,pct=14.0}, {id=16670,pct=13.0}, {id=13170,pct=12.5}, {id=13168,pct=10.8} },
          sections = {
            { id=4523, title="Knock Away", parent=0, child=0, sib=4524, order=1, spell=0, icon=132939, flags=1, cdisp=0,
              body="Highlord Omokk inflicts Physical damage to his current target, knocking them away." },
            { id=4524, title="Frenzy", parent=0, child=0, sib=0, order=2, spell=0, icon=136224, flags=0, cdisp=0,
              body="When Highlord Omokk reaches 50% remaining health, he goes into a frenzy, increasing his attack speed by $8269s1%." },
          },
        },
        { id=9236, name="Shadow Hunter Vosh'gajin", order=2,
          uiMapID=251, x=0.55327898264, y=0.69262301922, rootSection=4525,
          desc="Vosh'gajin is renowned for her beauty--and psychotic tendencies--among the trolls. A master of the shadow hunter arts, she wields formidable hexes, curses, and healing magics.",
          creatures = { {display=9732, file=607769, name="Shadow Hunter Vosh'gajin"} },
          loot = { {id=13255,pct=36.0}, {id=12654,pct=27.6}, {id=12626,pct=18.5}, {id=16712,pct=17.5}, {id=12653,pct=7.0}, {id=12651,pct=7.0}, {id=13257,pct=6.9} },
          sections = {
            { id=4525, title="Hex", parent=0, child=0, sib=4526, order=1, spell=0, icon=237579, flags=128, cdisp=0,
              body="Shadow Hunter Vosh'gajin transforms a random player into a frog, rendering them unable to attack or cast spells for $16097d." },
            { id=4526, title="Curse of Blood", parent=0, child=0, sib=0, order=2, spell=0, icon=136189, flags=320, cdisp=0,
              body="Shadow Hunter Vosh'gajin curses all players within $16098A1 yards, increasing their physical damage taken by 90 for $16098d." },
          },
        },
        { id=9237, name="War Master Voone", order=3,
          uiMapID=250, x=0.52459001541, y=0.54508197308, rootSection=4527,
          desc="During the Second War, Voone led small strike teams on daring missions into the heart of high elven territory. The cunning troll joined the false Horde because he wanted to be its chief strategist, not because he believed in Blackhand's ideology. Voone sees the splinter faction as an underdog, and he enjoys the satisfaction of overcoming insurmountable odds.",
          creatures = { {display=9733, file=607810, name="War Master Voone"} },
          loot = { {id=13173,pct=91.4}, {id=12335,pct=35.0}, {id=16676,pct=19.4}, {id=13179,pct=18.3}, {id=13177,pct=18.2}, {id=22231,pct=15.5}, {id=12582,pct=14.3} },
          sections = {
            { id=4527, title="Stage One: The Thrasher", parent=0, child=4528, sib=4529, order=1, spell=0, icon=0, flags=0, cdisp=0,
              body="War Master Voone attacks quickly, assaulting his enemies relentlessly." },
