        { id=10220, name="Halycon", order=7,
          uiMapID=254, x=0.37978100777, y=0.84016400576, rootSection=4572,
          desc="Halycon comes from a long line of great worgs bred for their ferocity and loyalty. Over the years, the den mother has produced an astonishing number of savage offspring. Rumors have spread that she is a demonic hound gifted to Rend Blackhand by a pit lord of the Burning Legion.",
