    { id=230, name="Dire Maul - Capital Gardens", isRaid=false, minLevel=55,
      mapID=429, loreFDID=608239, bgFDID=608161, buttonFDID=608200,
      desc="Built thousands of years ago to house the kaldorei's arcane secrets, the formerly great city of Eldre'Thalas now lies in ruin, writhing with warped, twisted forces. Competing covens once fought for control of Dire Maul's corrupted energy, but they have since settled into uneasy truces, choosing to exploit the power within their own territories rather than continue to battle over the entire complex.",
      encounters = {
        { id=11489, name="Tendris Warpwood", order=5,
          uiMapID=236, x=0.33606600761, y=0.53688502312, rootSection=4913,
          desc="Tendris Warpwood was a staunch defender of Eldre'Thalas, his heart inexorably entwined with the fate of the city. When the Sundering shattered the land, his resolve never wavered, but as corruption seeped into the ruins over the next 10,000 years, so too did it infect the ancient's spirit.",
          creatures = { {display=14383, file=607785, name="Tendris Warpwood"} },
