        { id=11488, name="Illyanna Ravenoak", order=6,
          uiMapID=236, x=0.20355199277, y=0.77663999796, rootSection=4906,
          desc="Illyanna Ravenoak, along with her faithful companion Ferra, was once Prince Tortheldrin's most valued hunter, until she refused to carry out her leader's order to execute her friends. As punishment, he killed Illyanna and her bear, but he used his demonic power to bind their spirits to their bodies, condemning them to remain in Dire Maul as undead protectors.",
          creatures = { {display=11270, file=607656, name="Illyanna Ravenoak"} },
          loot = { {id=18347,pct=24.3}, {id=18349,pct=24.2}, {id=18383,pct=23.9}, {id=18386,pct=22.0} },
          sections = {
