            { id=4910, title="Volley", parent=0, child=0, sib=4911, order=5, spell=0, icon=132222, flags=4, cdisp=0,
              body="Illyanna Ravenoak shoots a raining volley of arrows to all players within an area $30933A1 yards wide. Volley inflicts $448891s1 Arcane damage every $448891t1 sec for $30933d." },
            { id=4911, title="Immolation Trap", parent=0, child=0, sib=4912, order=6, spell=0, icon=135813, flags=160, cdisp=0,
              body="Illyanna Ravenoak throws an Immolation Trap nearby. The Immolation Trap lasts $22910d or until a player walks over it.\n\nThe Immolation Trap inflicts $78578s1 Fire damage every $78578t1 sec for $78578d to the player who triggers the trap." },
            { id=4912, title="Concussive Shot", parent=0, child=0, sib=0, order=7, spell=0, icon=135860, flags=128, cdisp=0,
              body="Illyanna Ravenoak dazes a player, reducing their movement speed by $22914s1% for $22914d.  Concussive Shot has a 50% chance to stun the player for $22915d instead." },
          },
        },
        { id=11487, name="Magister Kalendris", order=7,
          uiMapID=237, x=0.33879798651, y=0.45081999898, rootSection=4836,
          desc="When Prince Tortheldrin demanded the slaughter of the majority of his subjects, his most loyal lieutenants were tasked with executing his will. Magister Kalendris murdered many unsuspecting Shen'dralar without hesitation, but one of the doomed elves mortally wounded him during a destructive battle. Despite his demise, Kalendris's spirit still roams Dire Maul as a defender of Tortheldrin's rule.",
          creatures = { {display=14384, file=607703, name="Magister Kalendris"} },
          loot = { {id=18350,pct=25.2}, {id=18351,pct=23.4}, {id=18374,pct=19.9}, {id=18397,pct=19.4}, {id=18371,pct=8.7}, {id=22309,pct=0.4} },
          sections = {
