          loot = { {id=18395,pct=23.9}, {id=18382,pct=23.6}, {id=18380,pct=23.2}, {id=18378,pct=21.3}, {id=18396,pct=20.4}, {id=18392,pct=18.9}, {id=18376,pct=18.1}, {id=18375,pct=17.2}, {id=18388,pct=10.4}, {id=18373,pct=9.5} },
