              body="Hydrospawn inflicts $22419s1 Frost damage to all players within $22419r yards and knocks them back. Players affected by Riptide are disarmed for $22419d." },
            { id=5008, title="Massive Geyser", parent=0, child=0, sib=5009, order=3, spell=0, icon=135861, flags=32, cdisp=0,
              body="Hydrospawn summons a Massive Geyser that inflicts $22422s1 Frost damage to all players within $22422A1 yards and knocks them back." },
