        { id=11492, name="Alzzin the Wildshaper", order=4,
          uiMapID=240, x=0.56694000959, y=0.28893399239, rootSection=4921,
          desc="Alzzin the Wildshaper seeks nothing less than the total corruption of Feralas, but until he discovered the Shrine of Eldretharr in Dire Maul, he had little success. With the power of enslaved ancients at his command, Alzzin concentrated the vitality of the surrounding forest into his lair, allowing him to manipulate it at will.",
          creatures = { {display=14416, file=607533, name="Alzzin the Wildshaper"} },
          loot = { {id=18310,pct=19.0}, {id=18314,pct=19.0}, {id=18328,pct=19.0}, {id=18315,pct=19.0}, {id=18321,pct=18.9}, {id=18326,pct=18.7}, {id=18312,pct=18.7}, {id=18309,pct=18.7}, {id=18327,pct=18.7}, {id=18318,pct=18.5} },
