    { id=236, name="Stratholme - Main Gate", isRaid=false, minLevel=58,
      mapID=329, loreFDID=608255, bgFDID=608177, buttonFDID=608216,
      desc="Stratholme was once the jewel of northern Lordaeron, but today it is remembered for its harrowing fall to ruin. It was here that Prince Arthas turned his back on the noble paladin Uther Lightbringer, slaughtering countless residents believed to be infected with the horrific plague of undeath. Ever since, cursed Stratholme has been marred by death, betrayal, and hopelessness.",
      encounters = {
        { id=10558, name="Hearthsinger Forresten", order=0,
          uiMapID=317, x=0.60519099236, y=0.32699999213, rootSection=4794,
          desc="The Culling of Stratholme claimed the lives of innumerable people whose only crime was being in the doomed city. A traveling singer and piccolo player named Forresten was one such victim. He continues to wander the city in death, unable to accept his tragic fate.",
          creatures = { {display=10482, file=607637, name="Hearthsinger Forresten"} },
          loot = { {id=13378,pct=29.0}, {id=13383,pct=19.5}, {id=13384,pct=17.6}, {id=13379,pct=15.6}, {id=16682,pct=12.9} },
          sections = {
