        { id=11143, name="Postmaster Malown", order=2,
          uiMapID=317, x=0.55810201168, y=0.68405097723, rootSection=29847,
          desc="Malown didn't become the Postmaster by not caring about the mail. Even in his current state he is dedicated to maintaining the stability of the postal system. Should that system be disrupted to the point of threatening instability, Malown might just have to take matters into his own hands.",
