        { id=10997, name="Willey Hopebreaker", order=5,
          uiMapID=317, x=0.04282420129, y=0.50999999046, rootSection=4805,
          desc="Balnazzar took great pleasure in leveraging the cannon master Willey's destructive capabilities in undeath, calling his prized minion by the name of Hopebreaker. The dreadlord relishes that he has twisted Willey and other Scarlet Crusaders--who so despised the undead in life--into his unwitting pawns.",
