        { id=11501, name="King Gordok", order=16,
          uiMapID=235, x=0.31954398751, y=0.22948199511, rootSection=4666,
          desc="To rule the Gordok ogres, one must simply proclaim oneself king... and then destroy all who might disagree. King Gordok--then merely known as Ulrok--solidified his power by convincing a dozen of his people's strongest warriors to challenge the king at the same time. The wild melee left most of the contestants dead or wounded, and Ulrok's blade easily cut down the survivors and the battle-weary king. To this day, Gordok ogres speak in hushed tones about the \"Day of Da Blood.\"",
          creatures = { {display=11583, file=607673, name="King Gordok"} },
          loot = { {id=18521,pct=24.9}, {id=18524,pct=24.4}, {id=18527,pct=24.1}, {id=18525,pct=24.1}, {id=18523,pct=24.1}, {id=18522,pct=23.8}, {id=18520,pct=23.7}, {id=18526,pct=23.6}, {id=18780,pct=9.0}, {id=19258,pct=2.5} },
